/* Design-only, no server requests. Dates fixed at 24 September 2026 to match mobile examples. */
Object.assign(paths,{vaccine:'<path d="m14 3 7 7m-9-5 7 7M5 12l7-7 7 7-7 7H5v-7ZM3 21l3-3m3-8 3 3m-6 0 3 3"/>',parasite:'<path d="M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13Z"/>',visit:'<path d="M4 3v6a5 5 0 0 0 10 0V3M2 3h4m6 0h4M9 14v2a5 5 0 0 0 10 0v-3"/><circle cx="19" cy="10" r="3"/>',med:'<path d="m8 4-4 4a6 6 0 0 0 8 12l8-8a6 6 0 0 0-8-8Zm-3 7 8 8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 10h18"/>',late:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 10h18m-9 3v3m0 2h.01"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'});
const q=new URLSearchParams(location.search),current=q.get('screen'),raw=q.has('raw');
const C=(s,cls='')=>`<section class="card ${cls}">${s}</section>`;
const F=(label,val='',type='text',extra='')=>`<div class="field-block"><label>${label}<${type==='textarea'?'textarea':'input'} class="input" ${type==='textarea'?'':`type="${type}" value="${val}"`} ${extra}>${type==='textarea'?val+'</textarea>':''}</label></div>`;
const S=(label,values)=>`<div class="field-block"><label>${label}<select class="input">${values.map(v=>`<option>${v}</option>`).join('')}</select></label></div>`;
const T=(label,on=true)=>`<label class="check-row"><input type="checkbox" ${on?'checked':''}>${label}</label>`;
const button=(t,attrs='',secondary=false)=>`<button class="btn ${secondary?'secondary':'primary'}" ${attrs}>${t}</button>`;
const seg=(names,index=0,targets=[])=>`<div class="segmented">${names.map((s,i)=>targets[i]?link(targets[i],s,i===index?'selected':''):`<button type="button" data-segment aria-pressed="${i===index}" class="${i===index?'selected':''}">${s}</button>`).join('')}</div>`;
const sectionTitle=(name,id)=>`<div class="section-title"><h2>${name}</h2>${link(id,'Все '+I('arrow'))}</div>`;
const line=(name,meta)=>`<div class="record-line"><strong>${name}</strong><p>${meta}</p></div>`;
const due=(title,when,date,kind='soon',target='vaccine-done',ic='vaccine')=>`<div class="due-row">${I(ic)}<div class="copy"><strong>${title}</strong><p class="due-state ${kind}">${kind!=='later'?I(kind==='late'?'late':'calendar'):''}${when}${date?' · '+date:''}</p></div>${link(target,'<span>Сделано</span>','small-action')}</div>`;
const dues=()=>due('Блохи и клещи','Просрочено на 12 дней','12 сентября','late','parasite-plan-flea-complete','parasite')+due('Осмотр','Через 9 дней','3 октября','soon','visit-complete','visit')+due('Глисты','Через 11 дней','5 октября','soon','parasite-plan-worm-complete','parasite');
const chart=(large=false)=>`<svg class="mini-chart ${large?'chart-large':''}" viewBox="0 0 600 250" role="img" aria-label="Вес: 4,5 кг 12 марта; 4,4 кг 20 июня; 4,2 кг 12 сентября"><line x1="50" y1="38" x2="566" y2="38"/><line x1="50" y1="124" x2="566" y2="124"/><line x1="50" y1="210" x2="566" y2="210"/><text x="3" y="42">4,6 кг</text><text x="3" y="128">4,2 кг</text><text x="3" y="214">3,8 кг</text><path d="M65 60 L307 81 L555 124"/><circle cx="65" cy="60" r="6"/><circle cx="307" cy="81" r="6"/><circle cx="555" cy="124" r="6"/><text x="54" y="43">4,5</text><text x="295" y="63">4,4</text><text x="544" y="106">4,2</text><text x="50" y="240">12 марта</text><text x="282" y="240">20 июня</text><text x="508" y="240">12 сентября</text></svg>`;
const important=()=>C('<h2>Важно знать</h2><dl><dt>Аллергии</dt><dd>Курица</dd><dt>Хронические болезни</dt><dd>Хронический гастрит</dd><dt>Принимает сейчас</dt><dd>Лечебный корм · постоянно</dd></dl>'+link('pet-edit','Изменить в анкете'),'facts');
const actions=()=>btn('add','Добавить запись '+I('plus'))+btn('summary','Для врача',true);
function medical(dog=false,error=false){return shell(link('pets',I('back')+'Все питомцы')+`<div class="health-head">${art('avatar-'+(dog?'dog':'cat'),'avatar')}<div><h1>${dog?'Бобик':'Мурка'}</h1><p>${dog?'Собака · 5 лет':'Кошка · Сибирская · 3 года · стерилизована'}</p></div><div class="weight"><strong>${dog?'28':'4,2'} кг</strong><p>${dog?'Из анкеты, дата не указана':'−0,3 кг за 6 месяцев'}</p></div>${link(dog?'dog-edit':'pet-edit','Анкета '+I('arrow'))}</div>`+(error?'<div class="banner error" style="margin-bottom:24px">Не удалось обновить медкарту. Показаны ранее загруженные данные. '+link('medical','Повторить')+'</div>':'')+`<div class="health-grid"><div class="health-left">${dog?C('<button class="notice-close" data-dismiss aria-label="Скрыть подсказку">'+I('close')+'</button><h2>Начнём с заботы</h2><p>Добавьте прививки и обработки — даты будут под рукой.</p>'+link('dog-vaccine','Добавить прививку'),'facts'):C('<h2>Сроки</h2>'+dues()+link('due','Все сроки · 5'))+important()}<div class="health-actions">${dog?btn('dog-vaccine','Добавить запись '+I('plus'))+btn('dog-summary','Для врача',true):actions()}</div></div><div class="health-right">${C(sectionTitle('Прививки',dog?'vaccines-empty':'vaccines')+(dog?line('В анкете: привит','Даты и препараты не указаны'):line('Нобивак Tricat Trio','12 марта 2026 · Айболит')+line('Нобивак Rabies','12 марта 2026 · Айболит')))}${C(sectionTitle('Паразиты',dog?'parasites-empty':'parasites')+(dog?line('Пока нет записей','Обработки сохранятся здесь'):line('Бравекто Спот-он','20 июня · блохи и клещи')+line('Мильбемакс','5 июля · глисты')))}${C(sectionTitle('Визиты',dog?'visits-empty':'visits')+(dog?line('Пока нет записей','Диагнозы и назначения рядом'):line('Контрольный осмотр','Запланирован · 3 октября')+line('Обострение гастрита','2 августа · Айболит')))}${C(sectionTitle('Лекарства',dog?'medications-empty':'medications')+(dog?line('Не указано владельцем','Курсы из анкеты появятся здесь'):line('Лечебный корм','Сейчас · постоянно')+line('Фортифлора','Завершён · 2–15 августа')))}${C(sectionTitle('Вес',dog?'weight-one':'weight')+(dog?'<h3>28 кг</h3><p>Добавьте ещё одно измерение, чтобы увидеть изменения.</p>':chart(true)),'wide')}${C(sectionTitle('История проверок','pet-history')+line(dog?'Пока нет проверок':'1 августа · Наблюдаем',dog?'История появится после первой проверки':'Рвота два дня, отказ от еды'),'wide')}</div></div><div class="mobile-health-actions">${dog?btn('dog-vaccine','Добавить запись')+btn('dog-summary','Для врача',true):actions()}</div>`,'pets','Питомцы / '+(dog?'Бобик':'Мурка'))}
const rowPet=(name,meta,sp,id,status=false)=>`<div class="pet-table-row">${art('avatar-'+sp,'avatar')}<a class="copy" href="?screen=${id}"><h3>${name}</h3><p>${meta}</p>${status?'<span class="pet-due">Обработка от блох и клещей — просрочено</span>':''}</a>${status?badge('monitor'):''}${link(id,I('arrow'))}</div>`;
function dashboard(list=false){return shell(heading(list?'Питомцы · 2':'Всё для заботы о ваших питомцах',list?'Медкарта, планы и история каждого любимца.':'Здоровье питомцев и ближайшие дела — в одном месте.',list?btn('dog-edit','Добавить питомца '+I('plus')):'')+(!list?'<section class="welcome-panel"><div><h2>Что-то беспокоит?</h2><p>Расскажите, как чувствует себя питомец.</p></div>'+btn('check','Проверить симптомы '+I('arrow'))+'</section>':'')+`<div class="${list?'':'dashboard-columns'}">${C((list?'':sectionTitle('Ваши питомцы','pets'))+rowPet('Мурка','Сибирская · 3 года','cat','medical',true)+rowPet('Бобик','Собака · 5 лет','dog','medical-empty'))}${list?'':C('<h2>Последние проверки</h2>'+line('Мурка · 1 августа','Рвота, отказ от еды')+badge('monitor')+'<div class="divider"></div>'+link('history','Вся история '+I('arrow')))}</div>`,list?'pets':'dashboard')}
const rec=(date,text,target='record')=>`<a class="card record-card" href="?screen=${target}"><h3>${date}</h3><p>${text}</p></a>`;
const diseases=['Панлейкопения','Калицивироз','Ринотрахеит','Бешенство'];
function vaccines(empty=false){return shell(heading('Прививки',empty?'Бобик · Собака':'Мурка · Кошка',btn(empty?'dog-vaccine':'vaccine-done','Добавить прививку '+I('plus')))+`<div class="clinical-layout"><div class="record-list">${empty?C('<h2>Даты пока не записаны</h2><p>В анкете отмечено: привит. Добавьте сделанные прививки или запланируйте следующие.</p>'+link('dog-vaccine','Добавить прививку')):'<h3 class="group-label">Запланировано</h3>'+rec('12 марта 2027','Нобивак Tricat Trio<br>Нобивак Rabies','planned')+'<h3 class="group-label">Сделано</h3>'+rec('12 марта 2026','Нобивак Tricat Trio · Нобивак Rabies<br>Клиника «Айболит»')+rec('12 марта 2025','Нобивак Tricat Trio · Нобивак Rabies<br>Клиника «Айболит»','vaccine-2025')}</div><aside class="section-aside">${C('<h2>Основные прививки</h2>'+(empty?['Чума плотоядных','Парвовирусный энтерит','Аденовироз (инфекционный гепатит)','Бешенство']:diseases).map(d=>line(d,empty?'Нет записей':'Следующая — 12 марта 2027')).join('')+'<p class="footnote">Основные — прививки, которые ветеринары обычно рекомендуют всем '+(empty?'собакам':'кошкам')+'. Уточните у врача.</p>')}</aside></div>`,'pets','Медкарта / Прививки')}
const chipset=arr=>`<div class="chips">${arr.map(s=>`<button type="button" class="chip" aria-pressed="true">${s}</button>`).join('')}</div>`;
const products=[['Нобивак Tricat Trio','MSD · Инъекция · панлейкопения, калицивироз, ринотрахеит'],['Нобивак Rabies','MSD · Инъекция · бешенство'],['Пуревакс RCP','Boehringer Ingelheim · Инъекция · основные инфекции'],['Фелоцел CVR','Zoetis · Инъекция · основные инфекции'],['Мультифел-4','Ветбиохим · Инъекция · четыре инфекции'],['Пуревакс FeLV','Boehringer Ingelheim · Инъекция · лейкоз']];
const dogProducts=[['Нобивак DHPPi','MSD · Инъекция · чума, аденовироз, парвовирус, парагрипп'],products[1],['Нобивак L4','MSD · Инъекция · лептоспироз']];
const parasiteProducts=[['Бравекто Спот-он','MSD · Капли · блохи, клещи'],['Мильбемакс','Elanco · Таблетка · глисты'],['Профендер','Elanco · Капли · глисты']];
const productOptions=(arr)=>arr.map(([n,m],i)=>`<button type="button" role="option" aria-selected="false" id="product-${i}" class="product-result" data-product="${i}"><strong>${n}</strong><p>${m}</p></button>`).join('');
function catalog(open=false,parasite=false,dog=false,error=false){return `<div class="catalog-wrap" data-kind="${parasite?'parasite':dog?'dog':'cat'}"><label class="field-block">Найти препарат<input class="input" role="combobox" aria-label="Найти препарат" aria-expanded="${open}" aria-controls="catalog-options" aria-autocomplete="list" data-search placeholder="Название или производитель" autocomplete="off"></label><div class="product-box" ${open?'':'hidden'} data-dropdown>${error?'<div class="banner error">Список препаратов не загрузился</div>':''}<p class="footnote">Популярные для ${dog?'собак':'кошек'}</p><div id="catalog-options" role="listbox" aria-label="Препараты">${error?'':productOptions(parasite?parasiteProducts:dog?dogProducts:products)}</div><div class="product-fallback">${link('manual','Нет в списке — ввести название')}${link('targets','Без препарата — только от чего')}</div></div></div>`}
function position(name,targets,next='Через год — 24 сентября 2027',plan=false){return `<section class="position"><div class="position-head"><h3>${name}</h3><button type="button" class="icon-control" data-remove aria-label="Удалить ${name}">${I('close')}</button></div>${chipset(targets)}${plan?'':S('Следующая',[next,'Своя дата','Не напоминать'])+'<p class="field-help">По инструкции препарата. Уточните у врача.</p>'}</section>`}
function eventForm(kind='vaccine',plan=false,open=false,complete=false,dog=false,error=false){let para=kind==='parasite';let title=para?'Обработка от паразитов':'Прививка';return shell(heading(title,dog?'Бобик · Собака':'Мурка · Кошка',link(para?'parasites':dog?'vaccines-empty':'vaccines',I('back')+'В раздел'))+`<form class="health-form" data-demo-save><div class="card">${error?'<div class="banner error" style="margin-bottom:20px">Нет связи с сервером. Введённые данные сохранены в форме.</div>':''}${seg(['Сделано','Запланировать'],plan?1:0,[para?'parasite-done':dog?'dog-vaccine':'vaccine-done',para?'parasite-plan':'vaccine-plan'])}${F(plan?'Когда сделать':'Когда сделали',plan?'':'2026-09-24','date',plan?'min="2026-09-24" required':'max="2026-09-24" required')}<h3 style="margin-bottom:14px">${para?'Препараты':'Вакцины'}</h3>${catalog(open,para,dog,current==='catalog-error')}<div data-positions>${para?position('Бравекто Спот-он',['Блохи','Клещи'],'Через 12 недель — 17 декабря',plan)+(complete||plan?'':position('Мильбемакс',['Глисты'],'Через 3 месяца — 24 декабря')):position(plan?'Нобивак Rabies':dog?'Нобивак DHPPi':'Нобивак Tricat Trio',plan?['Бешенство']:dog?['Чума','Аденовироз','Парвовирус','Парагрипп']:diseases.slice(0,3),undefined,plan)+(plan||dog?'':position('Нобивак Rabies',['Бешенство']))}</div><button type="button" class="link" data-add-product>+ Добавить ${para?'препарат':'вакцину'}</button><div style="height:24px"></div>${F('Клиника · необязательно','Айболит')}${F('Заметка · необязательно','','textarea','maxlength="300"')}<div class="banner">${plan?'План появится в сроках медкарты.':complete?'Отметим только эту позицию. Следующий срок — 17 декабря; остальные планы сохранятся.':'У каждой позиции будет свой следующий срок. Проверьте даты перед сохранением.'}</div><div class="form-actions">${link(para?'parasites':'vaccines','Отмена')}${button('Сохранить','type="submit"')}</div></div></form>`,'pets','Медкарта / '+title)}
function parasites(){return shell(heading('Паразиты','Мурка · Обработки и следующие сроки',btn('parasite-done','Добавить обработку '+I('plus')))+`<div class="clinical-layout"><div class="record-list"><h3 class="group-label">Запланировано</h3>${rec('12 сентября','Бравекто Спот-он<br><span class="late">Просрочено на 12 дней</span>','parasite-plan-flea')}${rec('5 октября','Мильбемакс · глисты<br>Через 11 дней','parasite-plan-worm')}<h3 class="group-label">Сделано</h3>${rec('5 июля','Мильбемакс · глисты','parasite-july')}${rec('20 июня','Бравекто Спот-он · блохи, клещи','parasite-june')}</div><aside class="section-aside stack">${C('<h2>Блохи и клещи</h2>'+line('Последняя — 20 июня','Бравекто Спот-он')+'<p class="late">Просрочено на 12 дней</p>'+link('parasite-plan-flea-complete','Сделано'))}${C('<h2>Глисты</h2>'+line('Последняя — 5 июля','Мильбемакс')+'<p class="soon">Следующая — 5 октября</p>')}</aside></div>`,'pets','Медкарта / Паразиты')}
function weight(one=false){return shell(heading('Вес',one?'Бобик · Из анкеты':'Мурка · Измерения и изменения',btn('weight-new','Добавить вес '+I('plus')))+`<div class="clinical-layout"><div>${C(seg(['Полгода','Год','Всё'])+`<h2>${one?'28':'4,2'} кг</h2><p>${one?'Добавьте ещё одно измерение, чтобы увидеть изменения.':'−0,3 кг за 6 месяцев'}</p>`+(one?'':chart(true)))}${C('<h2>Измерения</h2>'+table(['Дата','Вес',''],one?[['Дата не указана','28 кг',link('weight-new','Уточнить')]]:[['12 сентября 2026','4,2 кг',link('weight-edit','Изменить')],['20 июня 2026','4,4 кг',link('weight-edit','Изменить')],['12 марта 2026','4,5 кг',link('weight-edit','Изменить')]]))}</div><aside class="section-aside">${C('<h2>Одна история веса</h2><p>Последнее измерение отображается и в анкете. Изменения веса показаны без оценки «норма» или «не норма».</p>','facts')}</aside></div>`,'pets','Медкарта / Вес')}
function weightForm(edit=false){return shell(heading(edit?'Изменить измерение':'Добавить вес','Мурка',link('weight',I('back')+'История веса'))+`<form class="health-form weight-entry" data-demo-save>${C(F('Вес, кг','4.2','number','min="0.1" max="200" step="0.1" required inputmode="decimal"')+F('Дата',edit?'2026-09-12':'2026-09-24','date','required max="2026-09-24"')+'<p class="footnote">Если на эту дату уже есть измерение, обновим его.</p><div class="form-actions">'+link('weight','Отмена')+button('Сохранить','type="submit"')+'</div>'+(edit?'<button type="button" class="link" style="color:var(--red)" data-confirm="Удалить измерение?">Удалить измерение</button>':''))}</form>`,'pets','Медкарта / Вес')}
function medications(){return shell(heading('Лекарства','Мурка · Сейчас: 1 · Всего: 2',btn('medication-new','Добавить лекарство '+I('plus')))+`<div class="clinical-layout"><div class="record-list"><h3 class="group-label">Сейчас</h3>${rec('Лечебный корм','По схеме врача<br>С 2 августа · постоянно','course')}<h3 class="group-label">Раньше</h3>${rec('Фортифлора','1 пакетик в день<br>2–15 августа 2026','medication-new')}</div><aside>${C('<h2>Назначения под рукой</h2><p>Дозировку назначает врач. Лапка помогает сохранить её вместе с датами курса.</p><div class="divider"></div><p>Текущие лекарства также видны в анкете.</p>','facts')}</aside></div>`,'pets','Медкарта / Лекарства')}
function medForm(){return shell(heading('Лекарство','Мурка',link('medications',I('back')+'В раздел'))+`<form class="health-form" data-demo-save>${C('<div data-med-positions>'+medPosition('Лечебный корм',true)+medPosition('Фортифлора',false)+'</div><button class="link" type="button" data-add-med>+ Ещё препарат</button><p class="field-help">Дозировку назначает врач. Мы только помогаем не забыть.</p><div class="form-actions">'+link('medications','Отмена')+button('Сохранить','type="submit"')+'</div>')}</form>`,'pets','Медкарта / Лекарство')}
let legacyMedPosition=(name,forever)=>`<section class="position">${F('Название',name)}${F('Как давать',forever?'По схеме врача':'1 пакетик в день')}${F('Начало','2026-08-02','date')}${T('Постоянно',forever)}${forever?'':F('Окончание','2026-08-15','date')}</section>`;
function visits(){return shell(heading('Визиты','Мурка · Диагнозы и назначения врача',btn('visit-done','Добавить визит '+I('plus')))+`<div class="clinical-layout"><div class="record-list"><h3 class="group-label">Запланировано</h3>${rec('3 октября 2026','Осмотр · Айболит<br><span class="soon">Через 9 дней</span>','visit-plan')}<h3 class="group-label">Сделано</h3>${rec('2 августа 2026','Болезнь · Айболит<br>Обострение хронического гастрита<br>'+badge('monitor')+'<br>По проверке 1 августа','visit-record')}</div><aside>${C('<h2>История лечения</h2><p>Сохраняйте назначения вместе с визитом. Их можно добавить в лекарства без повторного ввода.</p>','facts')}</aside></div>`,'pets','Медкарта / Визиты')}
function visitForm(plan=false){return shell(heading('Визит к врачу','Мурка',link('visits',I('back')+'В раздел'))+`<form class="health-form" data-demo-save>${C(seg(['Был','Запланировать'],plan?1:0,['visit-done','visit-plan'])+S('Вид визита',plan?['Осмотр или профилактика','Болезнь','Операция','Анализы и диагностика','Другое']:['Болезнь','Осмотр или профилактика','Операция','Анализы и диагностика','Другое'])+F(plan?'Когда посетить':'Когда были',plan?'2026-10-03':'2026-08-02','date',plan?'min="2026-09-24" required':'max="2026-09-24" required')+F('Клиника','Айболит')+F('Причина',plan?'Контрольный осмотр':'Рвота два дня, отказ от еды','textarea')+(plan?'':F('Диагноз','Обострение хронического гастрита','textarea')+'<h3 style="margin-bottom:16px">Назначения</h3><div data-prescriptions>'+prescription('Фортифлора','1 пакетик в день, 14 дней')+prescription('Лечебный корм','Постоянно')+'</div><button type="button" class="link" data-add-prescription>+ Добавить назначение</button><div style="height:20px"></div>'+S('Связать с проверкой',['1 августа · Наблюдаем','Не связывать']))+F('Заметка · необязательно','','textarea','maxlength="300"')+'<div class="form-actions">'+link('visits','Отмена')+button('Сохранить','type="submit"')+'</div>')}</form>`,'pets','Медкарта / Визит')}
let legacyPrescription=(name,how)=>`<section class="position">${F('Название',name)}${F('Как принимать',how)}${T('Добавить в лекарства')}</section>`;
function record(plan=false,visit=false,course=false){const title=course?'Лечебный корм':visit?'Визит к врачу':'Прививка';return shell(heading(title,'Мурка',`<div class="row">${btn(course?'medication-new':visit?'visit-done':plan?'vaccine-done':'vaccine-done',plan?'Сделано':'Изменить')}${plan?btn('vaccine-plan','Перенести',true):''}</div>`)+`<div class="clinical-layout"><div class="stack">${C('<span class="pill">'+(course?'Текущий курс':plan?'Запланировано':'Сделано')+'</span><h2 style="margin-top:16px">'+(course?'С 2 августа · постоянно':visit?'2 августа 2026':plan?'12 марта 2027':'12 марта 2026')+'</h2><p>'+(course?'По схеме врача':'Клиника «Айболит»')+'</p>')}${course?'':visit?C('<h3>Причина</h3><p>Рвота два дня, отказ от еды</p><div class="divider"></div><h3>Диагноз</h3><p>Обострение хронического гастрита</p><div class="divider"></div><h3>Назначения</h3>'+line('Фортифлора','1 пакетик в день, 14 дней')+line('Лечебный корм','Постоянно')+link('medications','Посмотреть лекарства')):C(line('Нобивак Tricat Trio','Панлейкопения, калицивироз, ринотрахеит')+line('Нобивак Rabies','Бешенство'))}</div><aside>${C('<h3>Действия с записью</h3><p style="margin:12px 0">'+(plan?'План остаётся в сроках, пока вы не отметите его сделанным или не отмените.':'Изменение записи отразится в медкарте и сводке для врача.')+'</p>'+button(course?'Завершить курс':plan?'Отменить план':'Удалить запись',`type="button" data-confirm="${course?'Завершить курс?':plan?'Отменить план?':'Удалить запись?'}"`,true),'facts')}</aside></div>`,'pets','Медкарта / Запись')}
function table(headers,rows){return `<table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((v,i)=>`<td data-label="${headers[i]}">${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
const vaccineTable=()=>table(['Болезнь','Последняя','Препарат','Следующая'],diseases.map((d,i)=>[d,'12.03.2026',i===3?'Нобивак Rabies':'Нобивак Tricat Trio','12.03.2027']));
function summary(dog=false){return shell(heading('Для врача',dog?'Бобик · Сведения владельца':'Мурка · Сведения владельца',`<div class="row no-print">${button('Распечатать','data-print',true)}${button('Сохранить PDF','data-print')}<p class="summary-print-note">В окне печати выберите «Сохранить как PDF».</p></div>`)+`<div class="summary-reading">${C(`<h2>${dog?'Бобик':'Мурка'}</h2><p>${dog?'Собака · 5 лет · 28 кг, из анкеты, дата не указана':'Кошка · Сибирская · 3 года · самка · стерилизована<br>Вес: 4,2 кг · 12 сентября 2026'}</p>`)}${C('<h2>Важно знать</h2>'+(dog?'<p>Не указано владельцем</p>':'<div class="summary-facts"><div>'+line('Аллергии','Курица')+line('Хронические болезни','Хронический гастрит')+'</div><div>'+line('Принимает сейчас','Лечебный корм · по схеме врача, постоянно с 2 августа')+'</div></div>'))}${C('<h2>Прививки</h2>'+(dog?'<p>В анкете: привит. Даты и препараты не указаны.</p>':vaccineTable()))}${C('<h2>Паразиты</h2>'+(dog?'<p>Не указано владельцем</p>':table(['Цель','Последняя обработка','Препарат','Следующая'],[['Блохи и клещи','20.06.2026','Бравекто Спот-он','12.09.2026 · просрочено'],['Глисты','05.07.2026','Мильбемакс','05.10.2026']])))}${C('<h2>Визиты за последний год</h2>'+(dog?'<p>Не указано владельцем</p>':table(['Дата / вид','Диагноз','Назначения'],[['02.08.2026 · Болезнь · Айболит','Обострение хронического гастрита','Фортифлора — 1 пакетик в день, 14 дней; лечебный корм — постоянно']])))}${C('<h2>Вес</h2>'+(dog?'<p>28 кг · из анкеты. Дата измерения не указана.</p>':chart()+line('12 сентября — 4,2 кг','20 июня — 4,4 кг · 12 марта — 4,5 кг')))}${C('<h2>Последние проверки</h2>'+(dog?'<p>Пока нет проверок</p>':badge('monitor')+line('1 августа 2026','Рвота, отказ от еды')))}<p class="footnote">Составлено владельцем в «Лапке» 24 сентября 2026. Не является ветеринарным документом.</p></div>`,'pets','Медкарта / Для врача')}
function printSample(){return `<article class="print-page">${logo()}<h1>Медкарта: Мурка</h1><p>Кошка · Сибирская · 3 года · самка · стерилизована<br>Вес 4,2 кг · 12 сентября 2026</p><h2>Важно знать</h2><p>Аллергии: курица. Хронический гастрит.<br>Лечебный корм: по схеме врача, постоянно с 2 августа.</p><h2>Прививки</h2>${vaccineTable()}<h2>Паразиты</h2><p>Блохи и клещи: 20 июня, Бравекто Спот-он. План 12 сентября: просрочено.<br>Глисты: 5 июля, Мильбемакс. План: 5 октября.</p><h2>Визиты за год</h2>${table(['Дата / вид','Диагноз','Назначения'],[['2 августа · Болезнь<br>Айболит','Обострение хронического гастрита','Фортифлора — 1 пакетик в день, 14 дней;<br>лечебный корм — постоянно']])}<h2>Вес</h2>${chart()}<p>12 марта: 4,5 кг · 20 июня: 4,4 кг · 12 сентября: 4,2 кг</p><h2>Последние проверки</h2><p>1 августа · НАБЛЮДАЕМ · Рвота, отказ от еды</p><footer>Составлено владельцем в «Лапке» 24 сентября 2026. Не является ветеринарным документом.<br>Страница 1 из 1.</footer></article>`}
function empty(kind){const names={parasites:['Паразиты','Обработок пока нет','Добавьте последнюю обработку — следующие сроки будут под рукой.','parasite-done','Добавить обработку','parasite'],visits:['Визиты','Визитов пока нет','Запишите диагноз и назначения после приёма.','visit-done','Добавить визит','visit'],medications:['Лекарства','Лекарств нет','Если врач назначит курс — сохраните его здесь.','medication-new','Добавить лекарство','med']};let [name,t,p,id,b,ic]=names[kind];return shell(heading(name,'Бобик')+C(I(ic)+`<h2>${t}</h2><p>${p}</p>`+btn(id,b),'empty-section'),'pets','Медкарта / '+name)}
function manual(noName=false){return shell(heading(noName?'Без препарата':'Свой препарат','Мурка',link('vaccine-done','Назад к записи'))+`<form class="health-form" data-demo-save>${C((noName?'<div class="banner">Название можно не указывать, если не помните препарат.</div>':F('Название препарата','','text','required'))+'<h3 style="margin-top:20px">От чего прививали</h3>'+chipset(diseases)+S('Следующая',['Не напоминать','Своя дата'])+'<p class="field-help">Срок для своего препарата не подставляется автоматически.</p><div class="form-actions">'+button('Добавить позицию','type="submit"')+'</div>')}</form>`,'pets','Медкарта / Своя запись')}
function petEdit(dog=false){return shell(heading('Анкета',dog?'Бобик':'Мурка',link(dog?'medical-empty':'medical','Медкарта'))+`<form class="health-form" data-demo-save>${C('<h3>Основное</h3><div class="divider"></div>'+S('Вид',dog?['Собака','Кот']:['Кот','Собака'])+F('Имя',dog?'Бобик':'Мурка')+F('Порода',dog?'':'Сибирская')+F('Возраст, лет',dog?'5':'3')+F('Вес, кг',dog?'28':'4,2')+(dog?'':'<p class="field-help">История веса — в медкарте</p>')+S('Пол',dog?['Кобель','Сука','Не указан']:['Кошка','Кот','Не указан'])+'<h3 style="margin:24px 0">Здоровье</h3>'+S('Стерилизация / кастрация',['Да','Нет','Не указано'])+S('Вакцинация',['Привит(а)','Нет'])+(dog?'':'<p class="field-help">В медкарте 4 позиции прививок</p>')+F('Аллергии',dog?'':'Курица')+F('Хронические болезни',dog?'':'Хронический гастрит')+F('Принимает препараты',dog?'':'Лечебный корм')+(dog?'':'<p class="field-help">Дозировка и даты — в медкарте</p>')+'<h3 style="margin:24px 0">Образ жизни</h3>'+S('Где бывает',['Дома','На улице','Дома и на улице'])+S('Питание',['Не указано','Сухой корм','Влажный корм','Смешанное','Натуральное'])+(dog?S('Размер',['Средний','Крупный','Маленький'])+S('Прогулки',['Ежедневные короткие','Редкие','Ежедневные длительные','Спорт']):'')+F('Заметки','','textarea')+'<div class="form-actions">'+link(dog?'medical-empty':'medical','Отмена')+button('Сохранить','type="submit"')+'</div>')}</form>`,'pets','Питомцы / Анкета')}

