const dateText=d=>d?d.split('-').reverse().join('.'):'Не указана';
function savedEvent(id,edit=false,complete=false){const source=savedEvents[id];const r=complete?{...source,plan:false,date:'2026-09-24',items:source.items.map(([name,targets])=>[name,targets,name==='Бравекто Спот-он'?'2026-12-17':name==='Мильбемакс'?'2026-12-24':'2027-09-24'])}:source;const content=edit?`<form class="health-form" data-demo-save>${C(`<span class="pill">${r.plan?'Запланировано':'Сделано'}</span><div style="height:20px"></div>${F(r.plan?'Дата плана':'Когда сделали',r.date,'date',r.plan?'required':'required max="2026-09-24"')}<div data-positions>${r.items.map(([name,targets,next])=>`<section class="position">${F('Препарат',name,'text','required')}${F('От чего',targets,'text','required')}${r.plan?'':F('Следующая дата · необязательно',next,'date')}</section>`).join('')}</div>${F('Клиника · необязательно',r.clinic||'')}${F('Заметка · необязательно',r.note||'','textarea','maxlength="300"')}<div class="form-actions">${link(id,'Отмена')}${button('Сохранить изменения','type="submit"')}</div>`)}</form>`:`<div class="clinical-layout"><div class="stack">${C(`<span class="pill">${r.plan?'Запланировано':'Сделано'}</span><h2 style="margin-top:16px">${r.dateLabel}</h2>${r.clinic?'<p>Клиника «'+r.clinic+'»</p>':''}`)}${C(r.items.map(([name,targets,next])=>line(name,targets+(next?'<br>Следующая дата: '+dateText(next):''))).join(''))}${r.note?C('<h3>Заметка</h3><p>'+r.note+'</p>'):''}</div><aside>${C('<h3>Действия с записью</h3><p style="margin:12px 0">'+(r.plan?'Измените план или отметьте процедуру сделанной.':'Сохранённые данные. Чтобы внести правки, нажмите «Изменить».')+'</p>'+button(r.plan?'Отменить план':'Удалить запись',`type="button" data-confirm="${r.plan?'Отменить план?':'Удалить запись?'}"`,true),'facts')}</aside></div>`;return shell(link(edit?id:r.section,I('back')+(edit?'К записи':'В раздел'))+heading(edit?(complete?'Отметить сделанным':'Изменить запись'):r.title,'Мурка',edit?'':`<div class="row">${r.plan?btn(id+'-complete','Сделано'):''}${btn(id+'-edit','Изменить',!!r.plan)}</div>`)+content,'pets','Медкарта / '+r.title)}

